import {build} from 'esbuild'
import {readFile} from 'node:fs/promises'
import path from 'node:path'
import type {TeamResultEntry} from '../../lib/team-results-contract'
const origin='http://127.0.0.1:4283'
let javascript='',stylesheet='',documentHtml=''
test.describe.configure({retries:0,timeout:25000})
const bundleNavigation=(firstParty=false)=>build({entryPoints:['tests/fixtures/mobile-navigation.ts'],bundle:true,platform:'browser',format:'esm',outfile:'fixture.js',write:false,jsx:'automatic',define:{TIQ_FIRST_PARTY_BUILD:String(firstParty)},loader:{'.module.css':'local-css'},alias:{'next/image':path.resolve('mobile/src/native-website-image.tsx'),'next/link':path.resolve('mobile/src/native-website-link.tsx')},plugins:[{name:'synthetic-account',setup(b){b.onResolve({filter:/^\.\.\/\.\.\/lib\/native-auth-storage$/},args=>args.importer.replace(/\\/g,'/').endsWith('/mobile/src/team-score-drafts.ts')?{path:path.resolve('tests/fixtures/mobile-native-draft-storage.ts')}:undefined);b.onResolve({filter:/^\.\/native-push$/},args=>args.importer.replace(/\\/g,"/").endsWith("/mobile/src/main.ts")?{path:path.resolve("tests/fixtures/mobile-native-coach-alerts.ts")}:undefined);b.onResolve({filter:/^@capacitor\/app$/},()=>({path:path.resolve('tests/fixtures/mobile-navigation-app.ts')}));b.onResolve({filter:/^@supabase\/supabase-js$/},()=>({path:path.resolve('tests/fixtures/mobile-navigation-client.ts')}))}}]})
test.beforeAll(async()=>{
 const bundle=await bundleNavigation()
 javascript=bundle.outputFiles.find(file=>file.path.endsWith('.js'))!.text
 stylesheet=(await Promise.all(['style.css','website-ui.css','app.css','website-parity.css','app-atmosphere.css','premium-surfaces.css'].map(file=>file==='app.css'?Promise.resolve(bundle.outputFiles.find(file=>file.path.endsWith('.css'))!.text):readFile('mobile/bundled/'+file,'utf8')))).join('\n')+'\n.preview-controls{padding:24px 12px 120px}.preview-controls button{min-height:44px}'
 documentHtml=await readFile('mobile/bundled/index.html','utf8')
})
test.beforeEach(async({page})=>{
 await page.route('**/*',async route=>{
  const url=new URL(route.request().url());if(url.origin!==origin)return route.abort()
  if(url.pathname==='/app.js')return route.fulfill({contentType:'text/javascript',body:javascript})
  if(url.pathname.endsWith('.css'))return route.fulfill({contentType:'text/css',body:url.pathname==='/style.css'?stylesheet+(url.searchParams.has('large')?'\n:root{font-size:22px!important}.native-calendar-screen .cal-body{inline-size:calc(100% - 18px)}':''):''})
  if(url.pathname.startsWith('/brand/')||url.pathname==='/logo.png')return route.fulfill({contentType:'image/png',body:await readFile('mobile/bundled'+url.pathname)})
  return route.fulfill({contentType:'text/html',body:url.searchParams.has('large')?documentHtml.replace('./style.css','./style.css?large=1'):documentHtml})
 })
})
async function bounded(page:Page){
 expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true)
 expect(await page.locator('.app-navigation').evaluate(el=>el.scrollWidth<=el.clientWidth)).toBe(true)
 for(const button of await page.locator('.app-tools-hub .app-tool:visible').all())expect(await button.evaluate(el=>el.scrollWidth<=el.clientWidth)).toBe(true)
}
const requestCount=(page:Page)=>page.evaluate(()=>(window as unknown as {navigationFixture:{requests:number}}).navigationFixture.requests)

async function useFirstPartyNavigation(page:Page) {
 const preview = await bundleNavigation(true)
 const previewScript = preview.outputFiles.find(file => file.path.endsWith('.js'))!.text
 await page.route(origin+'/app.js',route=>route.fulfill({contentType:'text/javascript',body:previewScript}))
}

async function recordScorecardCopies(page: Page, failFirst = false) {
 await page.evaluate(fail => {
  const copies: string[] = []
  let deny = fail
  Object.assign(window,{scorecardCopies:copies})
  Object.defineProperty(navigator,'clipboard',{configurable:true,value:{writeText:async(text:string)=>{
   if (deny) { deny = false; throw Error('Clipboard unavailable') }
   copies.push(text)
  }}})
 },failFirst)
}

