 await scorecard.getByRole('button',{name:'Edit scorecard',exact:true}).click()
 await page.getByRole('combobox',{name:'Venue (optional)',exact:true}).selectOption('vetta-sunset')
 await page.getByRole('button',{name:'Save scorecard',exact:true}).click()
 await expect(scorecard).toContainText('Vetta Sunset')
