test('first-party team chat lets a player report privately and retry a separate block',async({page},info)=>{
 await useFirstPartyNavigation(page)
 await page.setViewportSize({width:320,height:740})
 await page.goto(origin)
 await page.getByRole('navigation',{name:'Main navigation'}).getByRole('button',{name:/^Chats/}).click()
 await page.getByRole('button',{name:/^Baseline Aces/}).click()
 const post=page.getByText('Anyone up for a hit on Friday?',{exact:true})
 const messageActions=page.getByRole('button',{name:'Message actions for Teammate 0E4A',exact:true})
 const draft=page.getByRole('textbox',{name:'Message your team',exact:true})
 await draft.fill('Unsent practice plan')
 const openReport=async()=>{
  await messageActions.click()
  await page.getByRole('dialog').getByRole('button',{name:'Report message',exact:true}).click()
 }
 const report=page.getByRole('dialog',{name:'Report message',exact:true})
 await openReport()
 await expect(report.getByRole('heading')).toBeFocused()
 await report.getByRole('button',{name:'Cancel',exact:true}).click()
 await expect(messageActions).toBeFocused()
 await expect(draft).toHaveValue('Unsent practice plan')

 type SafetyFixture={chatSafetyFixture:{actions:Record<string,string>[];failNextReport:boolean;failNextBlock:boolean;blocked:boolean}}
 const fixture=()=>page.evaluate(()=>(window as unknown as SafetyFixture).chatSafetyFixture)
 expect((await fixture()).actions).toHaveLength(0)
 await page.evaluate(()=>{
  const state=(window as unknown as SafetyFixture).chatSafetyFixture
  state.failNextReport=true
  state.failNextBlock=true
 })
 await openReport()
 const reason=report.getByRole('combobox',{name:'Reason',exact:true})
 await reason.selectOption({label:'Unsafe meetup or other'})
 expect(await report.evaluate(el=>el.scrollWidth<=el.clientWidth)).toBe(true)
 await page.screenshot({path:info.outputPath('report-unsafe-meetup.png')})
 await report.getByRole('button',{name:'Send report',exact:true}).click()
 await expect(report.getByRole('status')).toContainText('Retry the same report')
 await expect(reason).toBeDisabled()
 await expect(reason).toHaveValue('other')
 await report.getByRole('button',{name:'Retry report',exact:true}).click()
 const reported=page.getByRole('dialog',{name:'Report sent',exact:true})
 await expect(reported.getByRole('heading')).toBeFocused()
 await expect(post).toBeVisible()
 expect((await fixture()).blocked).toBe(false)

 await reported.getByRole('button',{name:'Block chat posts',exact:true}).click()
 await expect(reported.getByRole('status')).toContainText('Couldn’t confirm the block')
 await reported.getByRole('button',{name:'Retry block',exact:true}).click()
 const blocked=page.getByRole('dialog',{name:'Chat posts blocked',exact:true})
 await blocked.getByRole('button',{name:'Done',exact:true}).click()
 await expect(post).toHaveCount(0)
 await expect(draft).toHaveValue('Unsent practice plan')
 const actions=(await fixture()).actions
 expect(actions.map(action=>action.action)).toEqual([
  'report_chat_message','report_chat_message','block_chat_member','block_chat_member',
 ])
 expect(actions[0]).toMatchObject({teamName:'Baseline Aces',messageId:'66666666-6666-4666-8666-666666666666',reason:'other'})
 expect(actions[1]).toEqual(actions[0])
 expect(actions[2]).toMatchObject({memberId:'77777777-7777-4777-8777-777777770E4A'})
 expect(actions[3]).toEqual(actions[2])

 await page.locator('.chat-room-options > summary').click()
 await page.getByRole('button',{name:/^Chat safety/}).click()
 await expect(page.getByRole('heading',{name:'Chat safety',exact:true})).toBeVisible()
 await page.getByRole('button',{name:'Unblock chat posts',exact:true}).click()
 await expect(page.getByText('Chat posts unblocked.',{exact:true})).toBeVisible()
 expect((await fixture()).blocked).toBe(false)
 await page.locator('.chat-room-options > summary').click()
 await page.getByRole('button',{name:/^Back to chat/}).click()
 await expect(post).toBeVisible()
})

