test('first-party Explore lets guests share a hitting invite from an empty events list',async({page},info)=>{
 await useFirstPartyNavigation(page)
 await page.clock.setFixedTime(new Date('2026-11-12T03:00:00Z'))
 await page.setViewportSize({width:390,height:844})
 await page.goto(origin+'/?signedOut=1')
 await page.getByRole('button',{name:'Explore without signing in',exact:true}).click()
 await expect(page.getByText('No upcoming events listed.',{exact:true})).toBeVisible()
 const reads=await requestCount(page)
 type InviteFixture={shares:ShareData[];copies:string[];failShare:boolean;failCopy:boolean}
 type InviteWindow=Window&{courtInviteFixture:InviteFixture}
 await page.evaluate(()=>{
  const state:InviteFixture={shares:[],copies:[],failShare:false,failCopy:false}
  Object.assign(window,{courtInviteFixture:state})
  Object.defineProperty(navigator,'share',{configurable:true,value:async(data:ShareData)=>{
   if(state.failShare)throw Error('Sharing unavailable')
   state.shares.push(data)
  }})
  Object.defineProperty(navigator,'clipboard',{configurable:true,value:{writeText:async(text:string)=>{
   if(state.failCopy)throw Error('Clipboard unavailable')
   state.copies.push(text)
  }}})
 })
 const trigger=page.getByRole('button',{name:'Invite to hit',exact:true})
 await trigger.click()
 const dialog=page.getByRole('dialog',{name:'Invite to hit',exact:true})
 const preview=dialog.getByRole('group',{name:'Invite preview'})
 const date=dialog.getByLabel('Date (optional)',{exact:true})
 const time=dialog.getByLabel('Central time (optional)',{exact:true})
 const quickDates=dialog.getByRole('group',{name:'Quick dates',exact:true})
 const today=quickDates.getByRole('button',{name:'Today',exact:true})
 const tomorrow=quickDates.getByRole('button',{name:'Tomorrow',exact:true})
 const flexible=quickDates.getByRole('button',{name:'Flexible',exact:true})
 const share=dialog.getByRole('button',{name:'Share invite',exact:true})
 const copy=dialog.getByRole('button',{name:'Copy invite',exact:true})
 await expect(dialog.getByRole('button',{name:'Save to Calendar',exact:true})).toHaveCount(0)
 const getFixture=()=>page.evaluate(()=>(window as unknown as InviteWindow).courtInviteFixture)
 await expect(time).toBeDisabled()
 await expect(flexible).toHaveAttribute('aria-pressed','true')
 await expect(preview).toContainText('What time works for you?')
 const club=dialog.getByRole('combobox',{name:'Tennis club',exact:true})
 await expect(club.locator('option')).toHaveText([
  'Vetta Concord Racquet Sports','Vetta Sunset','Vetta West Racquet Sports','Frontenac Racquet Club',
 ])
 const callClub=dialog.getByRole('link',{name:'Call club',exact:true})
 await expect(callClub).toHaveAttribute('href','tel:+13148423111')
 await expect(callClub).toHaveAccessibleDescription('(314) 842-3111 ext. 3')
 await club.selectOption('vetta-sunset')
 await expect(callClub).toHaveAttribute('href','tel:+13148492327')
 await club.selectOption('frontenac-racquet-club')
 await expect(callClub).toHaveAttribute('href','tel:+13149915599')
 await club.selectOption('vetta-west')
 await expect(callClub).toHaveAttribute('href','tel:+16364410006')
 await expect(callClub).toHaveAccessibleDescription('(636) 441-0006')
 await today.click()
 await expect(today).toHaveAttribute('aria-pressed','true')
 await expect(date).toHaveValue('2026-11-11')
 await expect(time).toBeEnabled()
 await tomorrow.click()
 await expect(tomorrow).toHaveAttribute('aria-pressed','true')
 await expect(today).toHaveAttribute('aria-pressed','false')
 await expect(date).toHaveValue('2026-11-12')
 await time.fill('18:30')
 await expect(preview).toContainText('Thursday, November 12, 2026 at 6:30 PM CST')
 await dialog.getByRole('heading',{name:'Invite to hit',exact:true}).focus()
 await page.screenshot({path:info.outputPath('explore-court-invite.png')})
 await flexible.click()
 await expect(flexible).toHaveAttribute('aria-pressed','true')
 await expect(date).toHaveValue('')
 await expect(time).toHaveValue('')
 await expect(time).toBeDisabled()
 await expect(preview).toContainText('Want to hit at Vetta West Racquet Sports? What time works for you?')
 await date.fill('2026-11-10')
 await share.click()
 await expect(dialog.getByRole('status')).toHaveText('Choose today or a future date.')
 await expect(date).toBeFocused()
 expect((await getFixture()).shares).toHaveLength(0)
 await date.fill('2026-11-14')
 await expect(quickDates.getByRole('button',{pressed:true})).toHaveCount(0)
 await time.fill('18:30')
 const body='Want to hit at Vetta West Racquet Sports on Saturday, November 14, 2026 at 6:30 PM CST?'
 await expect(preview).toContainText(body)
 await page.setViewportSize({width:320,height:844})
 expect(await dialog.evaluate(el=>el.scrollWidth<=el.clientWidth)).toBe(true)
 await share.click()
 await expect(dialog.getByRole('status')).toHaveText('Share sheet closed.')
 await copy.click()
 await expect(dialog.getByRole('status')).toHaveText('Invite copied.')
 const {shares,copies}=await getFixture()
 expect(shares).toHaveLength(1)
 expect(copies).toEqual([shares[0].text])
 const [message,links]=copies[0].split('\n\n')
 expect(message).toBe(body)
 const [apple,google]=links.split('\n')
 const destination='1330 Harvestowne Industrial Dr, St. Peters, MO 63304'
 expect(new URL(apple.replace('Apple Maps: ','')).searchParams.get('daddr')).toBe(destination)
 const googleMaps=new URL(google.replace('Google Maps: ',''))
 expect(googleMaps.origin+googleMaps.pathname).toBe('https://www.google.com/maps/dir/')
 expect(googleMaps.searchParams.get('api')).toBe('1')
 expect(googleMaps.searchParams.get('destination')).toBe(destination)

 await page.evaluate(()=>{Object.assign((window as unknown as InviteWindow).courtInviteFixture,{failShare:true,failCopy:true})})
 await share.click()
 await expect(dialog.getByRole('status')).toContainText('You can copy the invite instead.')
 await copy.click()
 const fallback=dialog.getByRole('textbox',{name:'Invite text'})
 await expect(fallback).toHaveValue(copies[0])
 await expect(fallback).toBeFocused()
 await dialog.getByRole('button',{name:'Close',exact:true}).click()
 await expect(dialog).toHaveCount(0)
 await expect(trigger).toBeFocused()
 expect(await requestCount(page)).toBe(reads)
})

