test.describe('Calendar shortcuts across club midnight',()=>{
 test.use({timezoneId:'America/Los_Angeles'})
 test('first-party My Lab uses the club date for hitting plans and scorecards',async({page},info)=>{
  await useFirstPartyNavigation(page)
  await page.clock.setFixedTime(new Date('2026-11-12T05:50:00Z'))
  await page.setViewportSize({width:320,height:740})
  await page.goto(origin+'/?unlinked=1&large=1')
  const nav=page.getByRole('navigation',{name:'Main navigation'})
  const lab=nav.getByRole('button',{name:'My Lab',exact:true})
  const explore=nav.getByRole('button',{name:'Explore',exact:true})
  await expect(page.locator('.lab-up-next button').first()).not.toContainText('Matches, lessons and practice.')
  await explore.click()
  await page.evaluate(()=>{
   const {calendarFixture}=(window as unknown as CalendarPreviewWindow)
   const hit={...calendarFixture.personal[0],kind:'match' as const,recurrenceRule:'' as const,
    location:'Vetta Sunset — 10911 Gravois Industrial Ct, St. Louis, MO 63128'}
   calendarFixture.competitions=[];calendarFixture.coach=[]
   calendarFixture.personal=[
    {...hit,id:'player-calendar-bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',title:'Evening hit',date:'2026-11-11',time:'18:30',
     hittingPlan:{clubId:'vetta-sunset',confirmedFor:'2026-11-11T18:30'}},
    {...hit,id:'player-calendar-cccccccc-cccc-4ccc-8ccc-cccccccccccc',title:'Midnight hit',date:'2026-11-12',time:'00:03',
     hittingPlan:{clubId:'vetta-sunset',confirmedFor:'2026-11-12T00:03'}},
   ]
  })
  await page.clock.setFixedTime(new Date('2026-11-12T05:56:00Z'))
  await lab.click()
  await expect(page.getByRole('button',{name:/Earlier today Evening hit Open scorecard/})).toBeVisible()
  await explore.click()
  const reads=await calendarRequestCount(page)
  await page.clock.setFixedTime(new Date('2026-11-12T06:00:01Z'))
  await lab.click()
  const yesterday=page.getByRole('button',{name:/Yesterday · CT Evening hit Open scorecard/})
  await expect(yesterday).toBeVisible()
  expect(await calendarRequestCount(page)).toBe(reads+1)
  await yesterday.screenshot({path:info.outputPath('my-lab-yesterdays-hit.png')})
  await explore.click()
  await page.clock.setFixedTime(new Date('2026-11-12T06:04:00Z'))
  await lab.click()
  await page.getByRole('button',{name:/Earlier today · CT Midnight hit Open scorecard/}).click()
  const editor=page.locator('[data-match-editor]')
  const date=editor.getByLabel('Match date',{exact:true})
  await expect(date).toHaveValue('2026-11-12')
  await expect(date).toHaveAttribute('max','2026-11-12')
  await editor.getByLabel('Opponent or doubles team').fill('Taylor')
  await editor.getByLabel('Format',{exact:true}).selectOption('singles')
  await editor.getByLabel('Score',{exact:true}).fill('6-4 6-3')
  await editor.getByLabel('Result',{exact:true}).selectOption('Won')
  await editor.getByRole('button',{name:'Save scorecard',exact:true}).click()
  await expect(page.getByText('Scorecard saved.',{exact:true})).toBeVisible()
  expect(await calendarRequestCount(page)).toBe(reads+1)
 })
})

