test('first-party Explore shows the signed-in player’s latest rated visit on request',async({page},info)=>{
 await useFirstPartyNavigation(page)
 await page.setViewportSize({width:320,height:740})
 await page.goto(origin+'/?unlinked=1')
 type FixtureWindow=Window&typeof import('../fixtures/mobile-personal-matches')&{switchNavigationOwner:()=>void}
 const owner='11111111-1111-4111-8111-111111111111',other='22222222-2222-4222-8222-222222222222'
 await page.evaluate(({owner,other})=>{
  const fixture=(window as unknown as FixtureWindow).personalMatchFixture
  const visit=(account:string,venue:string,date:string,surface:number|null,lighting:number|null,court_time:number|null)=>({
   id:crypto.randomUUID(),revision:crypto.randomUUID(),owner_user_id:account,created_at:date+'T12:00:00.000Z',
   match_date:date,calendar_match_id:null,opponent:'Private opponent',format:'singles' as const,outcome:'Won' as const,score:'6-4 6-3',
   court_venue_key:venue,court_feedback:surface||lighting||court_time?{surface,lighting,court_time}:null,
  })
  fixture.rows.push(
   visit(owner,'vetta-west','2026-11-02',1,1,null),
   visit(owner,'vetta-west','2026-11-04',4,null,5),
   visit(owner,'vetta-west','2026-11-08',null,null,null),
   visit(owner,'dwight-davis','2026-11-06',3,null,null),
   visit(other,'vetta-west','2026-11-09',null,2,null),
  )
 },{owner,other})
 const reads=()=>page.evaluate(()=>(window as unknown as FixtureWindow).personalMatchFixture.courtFeedbackReads)
 const nav=page.getByRole('navigation',{name:'Main navigation'})
 const explore=nav.getByRole('button',{name:'Explore',exact:true})
 const dialog=page.getByRole('dialog',{name:'Court info',exact:true})
 const disclosure=dialog.getByText('Your court ratings',{exact:true})
 const close=dialog.getByRole('button',{name:'Close',exact:true})
 await explore.click()
 await page.getByRole('button',{name:'Court info for Dwight Davis Tennis Center',exact:true}).click()
 expect(await reads()).toEqual([])
 await disclosure.click()
 await expect(dialog).toContainText('3 out of 5 stars')
 await expect(dialog).toContainText('Nov 6, 2026')
 await close.click()

 const openWest=async()=>{
  await page.getByRole('button',{name:'Find courts near me',exact:true}).click()
  const finder=page.getByRole('dialog',{name:'Find courts',exact:true})
  await finder.getByRole('searchbox',{name:'Court, city or ZIP'}).fill('Vetta West')
  await finder.getByRole('button',{name:'Search',exact:true}).click()
  await finder.getByRole('button',{name:'Court info for Vetta West Racquet Sports',exact:true}).click()
 }
 await openWest()
 await page.evaluate(()=>{(window as unknown as FixtureWindow).personalMatchFixture.failCourtFeedbackRead=true})
 await disclosure.click()
 await expect(dialog).toContainText('Couldn’t load your court ratings.')
 await page.evaluate(()=>{(window as unknown as FixtureWindow).personalMatchFixture.failCourtFeedbackRead=false})
 await dialog.getByRole('button',{name:'Retry ratings',exact:true}).click()
 await expect(dialog).toContainText('Nov 4, 2026')
 await expect(dialog).toContainText('4 out of 5 stars')
 await expect(dialog).toContainText('5 out of 5 stars')
 await expect(dialog).not.toContainText('Lighting')
 await expect(dialog).not.toContainText('Private opponent')
 expect(await dialog.evaluate(el=>el.scrollWidth<=el.clientWidth)).toBe(true)
 const starEdges=await dialog.locator('.court-rating-list dd').evaluateAll(rows=>rows.map(row=>Math.round(row.getBoundingClientRect().right)))
 expect(new Set(starEdges).size).toBe(1)
 await page.screenshot({path:info.outputPath('explore-private-court-ratings.png')})
 await disclosure.click();await disclosure.click()
 await expect(dialog).toContainText('Nov 4, 2026')
 const expected=(owner:string,venue:string)=>({owner,venue,limit:1,columns:'owner_user_id,court_venue_key,match_date,court_feedback'})
 expect(await reads()).toEqual([expected(owner,'dwight-davis'),expected(owner,'vetta-west'),expected(owner,'vetta-west')])

 await dialog.getByRole('button',{name:'Invite here',exact:true}).click()
 const invite=page.getByRole('dialog',{name:'Invite to hit',exact:true})
 await expect(invite).toBeVisible()
 await page.evaluate(()=>(window as unknown as FixtureWindow).switchNavigationOwner())
 await expect(invite).toHaveCount(0)
 await expect(dialog).toHaveCount(0)
 await explore.click()
 await openWest()
 await disclosure.click()
 await expect(dialog).toContainText('Nov 9, 2026')
 await expect(dialog).toContainText('2 out of 5 stars')
 await expect(dialog).not.toContainText('Surface condition')
 expect((await reads()).at(-1)).toEqual(expected(other,'vetta-west'))
})

