 const saveOptions=privateCourt.getByRole('group',{name:'Save Practice Court',exact:true})
 await saveOptions.getByRole('button',{name:'Home court',exact:true}).click()
 await saveOptions.getByRole('button',{name:'Favorite',exact:true}).click()

 const edit=finder.getByRole('button',{name:'Edit private court Practice Court',exact:true})
 const name=finder.getByLabel('Court name',{exact:true}),street=finder.getByLabel('Street address',{exact:true})
 await edit.click()
