 await street.fill('125 Preview Lane')
 await page.setViewportSize({width:320,height:844})
 expect(await finder.evaluate(el=>el.scrollWidth<=el.clientWidth)).toBe(true)
 await page.screenshot({path:info.outputPath('edit-private-court.png')})
 await save.click()
 await expect(finder.getByText('Private court updated.',{exact:true})).toBeVisible()
 await expect(finder.getByRole('button',{name:'Edit private court Evening Practice Court',exact:true})).toBeFocused()
 const saved=finder.getByRole('region',{name:'Saved courts',exact:true})
 await expect(saved.getByRole('heading',{level:4})).toHaveText(['Evening Practice Court'])
 await expect(saved).toContainText('Home court')

 await page.reload()
 await explore.click();await page.getByRole('button',{name:'Invite to hit',exact:true}).click()
 const club=invite.getByRole('combobox',{name:'Tennis club',exact:true})
 await expect(club).toHaveValue('vetta-concord')
 await expect(club.locator('option')).toHaveCount(4)
 await expect(club.locator('option').filter({hasText:'Evening Practice Court'})).toHaveCount(0)
 await recordScorecardCopies(page)
 await invite.getByRole('button',{name:'Copy invite',exact:true}).click()
 await expect(invite.getByText('Invite copied.',{exact:true})).toBeVisible()
 const [message]=await page.evaluate(()=>(window as unknown as {scorecardCopies:string[]}).scorecardCopies)
 expect(message).toContain('Want to hit at Vetta Concord Racquet Sports?')
 expect(message).not.toContain('Evening Practice Court')
 expect(decodeURIComponent(message)).not.toContain('125 Preview Lane')
 const address='125 Preview Lane, St. Louis, MO 63109'
 await invite.getByRole('button',{name:'Close',exact:true}).click()
 await finderButton.click()
 const privateDirection=finder.locator('[data-finder-saved]').getByRole('button',{name:'Directions to Evening Practice Court',exact:true})
 await page.evaluate(()=>{window.open=(url)=>{document.body.dataset.mapsUrl=String(url);return null}})
 await privateDirection.click()
 const directions=page.getByRole('dialog',{name:'Directions',exact:true})
 await expect(directions).toContainText(address)
 await directions.getByRole('button',{name:'Google Maps',exact:true}).click()
 await expect(directions).toHaveCount(0)
 await expect(privateDirection).toBeFocused()
 const route=new URL((await page.locator('body').getAttribute('data-maps-url'))!)
 expect(route.origin+route.pathname).toBe('https://www.google.com/maps/dir/')
