for (const width of [320, 390]) test(`Recent matches puts filtered scorecards within reach at ${width}px`, async ({page}, info) => {
  await page.setViewportSize({width, height:844})
  await page.goto(origin + `/?lab-opponents=1${width === 320 ? '&large=1' : ''}`)
  const recent = page.locator('#recent-results')
  const list = recent.locator('.recent-match-list')
  const summary = list.locator('summary')
  const scoreboard = page.locator('.lab-scoreboard')
  const jump = scoreboard.getByRole('button', {name:'Recent scorecards', exact:true})
  const heading = recent.getByRole('heading', {name:'Recent matches', exact:true})
  const back = recent.getByRole('button', {name:'Back to scoreboard', exact:true})
  await expect(summary.getByText('Match scorecards', {exact:true})).toBeVisible()
  await expect(summary).toContainText('10 matches')
  expect(await summary.evaluate(el => el.getBoundingClientRect().bottom <= document.querySelector('.result-view-controls')!.getBoundingClientRect().top)).toBe(true)
  await expect(list).not.toHaveAttribute('open', '')
  await expect(back).toHaveCount(0)
  await expect(jump).toHaveCSS('background-image',/linear-gradient.*linear-gradient.*linear-gradient/)
  await jump.tap()
  await expect(heading).toBeFocused()
  await expect(heading).toBeInViewport({ratio:1})
  await expect(list).toHaveAttribute('open', '')
  await expect(list.getByRole('button',{name:/Oct 28, 2026.*vs Casey Rivera/})).toBeVisible()
  const doubles = recent.getByRole('group', {name:'Match type', exact:true}).getByRole('button', {name:'Doubles', exact:true})
  await doubles.tap()
  await expect(doubles).toHaveAttribute('aria-pressed', 'true')
  await expect(list).toHaveAttribute('open', '')
  await expect(summary).toContainText('6 doubles matches')
  await expect(list.locator('.recent-scorecard:visible')).toHaveCount(6)
  await bounded(page)
  await recent.locator('h2').evaluate(el => el.scrollIntoView({block:'start'}))
  await page.screenshot({path:info.outputPath('my-lab-match-scorecards.png')})
  const scorecard = list.getByRole('button', {name:/Oct 27, 2026/})
  await expect(list.getByRole('button',{name:/Oct 26, 2026.*vs Casey Rivera & Morgan Wells/})).toBeVisible()
  await expect(scorecard.locator('.recent-scorecard-opponent')).toHaveCount(0)
  await scorecard.tap()
  await expect(page.locator('#match-detail .scorecard-meta')).toContainText('Oct 27, 2026 · doubles')
  await expect(page.locator('#match-detail .match-recorded-score')).toHaveText('6-4, 6-3')
  await expect(page.getByRole('region', {name:'Players on court', exact:true})).toContainText('No players are listed for this match.')
  const share = page.getByRole('button', {name:'Review scorecard sharing', exact:true})
  await share.tap()
  const preview = page.getByRole('dialog', {name:'Share public scorecard', exact:true})
  await expect(preview.getByRole('status')).toContainText('A current public scorecard is unavailable')
  await expect(preview.getByRole('button', {name:'Copy scorecard details', exact:true})).toHaveCount(0)
  await preview.getByRole('button', {name:'Back to match details', exact:true}).tap()
  await expect(share).toBeFocused()
  await page.getByRole('button', {name:'Back to My Lab', exact:true}).tap()
  await expect(scorecard).toBeFocused()
  await expect(doubles).toHaveAttribute('aria-pressed', 'true')
  await expect(list).toHaveAttribute('open', '')
  await back.tap()
  await expect(scoreboard.getByRole('heading',{name:'Jordan Lee',exact:true})).toBeFocused()
  await expect(scoreboard.getByRole('heading',{name:'Jordan Lee',exact:true})).toBeInViewport({ratio:1})
  await jump.tap()
  await expect(doubles).toHaveAttribute('aria-pressed', 'true')
  await expect(list).toHaveAttribute('open', '')
})

test('My Lab offers a first-scorecard path only when match history is empty',async({page},info)=>{
  await page.setViewportSize({width:320,height:844})
  await page.goto(origin+'/?large=1')
  await page.locator('.preview-controls').evaluate(el=>{(el as HTMLElement).hidden=true})
  const results=page.locator('#results-content')
  await expect(results).toHaveAttribute('data-state','ready')
  const first=page.getByRole('heading',{name:'Your first scorecard',exact:true})
  await expect(first).toHaveCount(0)

  await page.getByRole('button',{name:'Explore',exact:true}).click()
  await page.evaluate(()=>{
    const fixture=(window as unknown as LabProfilePreviewWindow).labProfileFixture
    fixture.deferMatches()
    fixture.setMatches('unavailable')
  })
  await page.getByRole('button',{name:'My Lab',exact:true}).click()
  await expect(results).toHaveText('Loading your latest matches…')
  await expect(first).toHaveCount(0)
  await page.evaluate(()=>(window as unknown as LabProfilePreviewWindow).labProfileFixture.releaseMatches())
  const retry=results.getByRole('button',{name:'Retry matches',exact:true})
  await expect(retry).toBeVisible()
  await expect(first).toHaveCount(0)

  await page.evaluate(()=>(window as unknown as LabProfilePreviewWindow).labProfileFixture.setMatches('empty'))
  await retry.click()
  await expect(page.locator('.lab-scoreboard + #recent-results')).toContainText('Your first scorecard')
  await page.getByRole('button',{name:'First scorecard',exact:true}).click()
  await expect(first).toBeVisible()
  await expect(first).toBeFocused()
  await expect(page.locator('.lab-form-strip')).toHaveCount(0)
  await bounded(page)
  await page.screenshot({path:info.outputPath('my-lab-first-scorecard.png')})

  const drills=results.getByRole('button',{name:'Try a drill',exact:true})
  await drills.tap()
  const training=page.getByRole('dialog',{name:'Level Up training',exact:true})
  await expect(training.getByRole('heading',{name:'Split-Step Rhythm',exact:true})).toBeVisible()
  await training.getByRole('button',{name:'Close Level Up',exact:true}).tap()
  await expect(drills).toBeFocused()
  await results.getByRole('button',{name:'Find a match',exact:true}).click()
  await expect(page.getByRole('heading',{name:'Compete',exact:true})).toBeFocused()
  await expect(page.locator('.app-hub-heading + [data-compete-discovery]')).toBeVisible()
})

test('My Lab starter warm-up confirms completion for the current visit without recording a session',async({page},info)=>{
 await page.setViewportSize({width:320,height:844})
 await page.clock.install()
 await page.goto(origin+'/?unlinked=1&large=1&free-training=1&training-inbox-review=1')
 await page.locator('.preview-controls').evaluate(el=>{(el as HTMLElement).hidden=true})
 const tryDrill=page.getByRole('button',{name:'Try a drill',exact:true})
 const receipt=page.locator('[data-lab-warmup-receipt]')
 await tryDrill.tap()
 const training=page.getByRole('dialog',{name:'Level Up training',exact:true})
 const start=training.getByRole('button',{name:'Start warm-up',exact:true})
 await expect(start).toBeInViewport({ratio:1})
 await expect(start).toHaveAccessibleDescription(/Use the timer for this visit/)
 await expect(training.getByRole('button',{name:'Start training',exact:true})).toHaveCount(0)
 await start.tap()
 await training.getByRole('button',{name:'Close Level Up',exact:true}).tap()
 await expect(tryDrill).toBeFocused()
 await expect(receipt).toBeEmpty()
 await tryDrill.tap()
 await start.tap()
 await expect(training.getByRole('heading',{name:'Warm-up',exact:true})).toBeFocused()
 const elapsed=training.getByRole('timer')
 await expect(training.getByRole('heading',{name:'Your routine',exact:true})).toBeVisible()
 await expect(training.locator('[data-proof]')).toHaveCount(0)
 await page.clock.runFor(2200)
 await expect(elapsed).not.toHaveText('00:00')
 await training.getByRole('button',{name:'Pause timer',exact:true}).tap()
 const paused=await elapsed.innerText()
 await page.clock.runFor(2200)
 await expect(elapsed).toHaveText(paused)
 await training.getByRole('button',{name:'Resume timer',exact:true}).tap()
 await page.clock.runFor(2200)
 await expect(elapsed).not.toHaveText(paused)
 await page.evaluate(()=>{
  Object.defineProperty(document,'visibilityState',{configurable:true,value:'hidden'})
  document.dispatchEvent(new Event('visibilitychange'))
  Reflect.deleteProperty(document,'visibilityState')
 })
 await expect(training.locator('[data-timer-hint]')).toHaveText('Paused while the app was in the background.')
 expect(await training.evaluate(el=>el.scrollWidth<=el.clientWidth+1)).toBe(true)
 const finish=training.getByRole('button',{name:'Finish warm-up',exact:true})
 await expect(finish).toBeInViewport({ratio:1})
 await page.screenshot({path:info.outputPath('my-lab-starter-warm-up.png')})
 const [minutes,seconds]=(await elapsed.innerText()).split(':').map(Number)
 await finish.tap()
 await expect(training).toHaveCount(0)
 await expect(tryDrill).toBeFocused()
 await expect(receipt).toContainText('Warm-up complete')
 await expect(receipt).toContainText(`Split-Step Rhythm · ${minutes}m ${seconds}s`)
 await expect(receipt).toBeInViewport({ratio:1})
 await page.screenshot({path:info.outputPath('my-lab-warm-up-complete.png')})
 expect(await page.evaluate(()=>(window as unknown as {navigationFixture:{trainingWrites:number}}).navigationFixture.trainingWrites)).toBe(0)
 await page.getByRole('button',{name:'Explore',exact:true}).tap()
 await page.getByRole('button',{name:'My Lab',exact:true}).tap()
 await expect(receipt).toBeEmpty()
})

test('My Lab scorecard search keeps the filter and finds newly loaded matches',async({page},info)=>{
  await page.setViewportSize({width:320,height:844})
  await page.goto(origin+'/?lab-search-history=1&large=1')
  await page.locator('.preview-controls').evaluate(el=>{(el as HTMLElement).hidden=true})
  await page.getByRole('button',{name:'Recent scorecards',exact:true}).click()
  const recent=page.getByRole('region',{name:'Recent matches',exact:true})
  const panel=recent.locator('.recent-match-list')
  const input=panel.getByRole('searchbox',{name:'Find a scorecard',exact:true})
  const status=panel.locator('[data-scorecard-search-status]')
  const cards=panel.locator('.recent-scorecard:visible')
  const singles=recent.getByRole('button',{name:'Singles',exact:true})
  await singles.click()
  await input.fill('CITY tennis')
  await expect(status).toHaveText('4 of 4 scorecards shown.')
  await input.fill('alex city')
  await expect(status).toHaveText('No loaded scorecards match.')
  await expect(input).toBeFocused()
  await expect(cards).toHaveCount(0)
  const clear=panel.getByRole('button',{name:'Clear search',exact:true})
  await clear.click();await expect(input).toBeFocused();await expect(input).toHaveValue('')
  await expect(cards).toHaveCount(4)
  await input.fill('alex city')
  const older=panel.getByRole('button',{name:'Load older matches',exact:true})
  await older.evaluate(el=>el.scrollIntoView({block:'center'}))
  await bounded(page)
  await page.screenshot({path:info.outputPath('my-lab-search-no-matches.png')})
  await page.evaluate(()=>(window as unknown as LabProfilePreviewWindow).labProfileFixture.deferMatches())
  await older.click()
  await expect(panel.getByRole('button',{name:'Loading older matches...',exact:true})).toBeDisabled()
  await input.fill('alex city')
  await input.evaluate((el:HTMLInputElement)=>el.setSelectionRange(4,4))
  await page.evaluate(()=>(window as unknown as LabProfilePreviewWindow).labProfileFixture.releaseMatches())
  await expect(status).toHaveText('1 of 5 scorecards shown.')
  await expect(input).toBeFocused();await expect(input).toHaveValue('alex city')
  expect(await input.evaluate((el:HTMLInputElement)=>el.selectionStart)).toBe(4)
  await expect(singles).toHaveAttribute('aria-pressed','true')
  const found=panel.getByRole('button',{name:/Oct 16, 2026.*vs Álex Rowan/})
  await expect(cards).toHaveCount(1)
  await found.click()
  await expect(page.locator('#match-detail .scorecard-meta')).toContainText('Oct 16, 2026 · singles')
  await page.getByRole('button',{name:'Back to My Lab',exact:true}).click()
  await expect(found).toBeFocused();await expect(input).toHaveValue('alex city')
  await expect(cards).toHaveCount(1)
})

