 if(category==='Leagues')await page.locator('[data-public-sign-in]').click()
 else await page.locator('.public-sign-in').getByRole('button',{name:'Sign in',exact:true}).click()
 const account=page.locator('.welcome-account')
 const password=account.getByLabel('Password',{exact:true}),signIn=account.getByRole('button',{name:'Sign in',exact:true})
 await account.getByRole('textbox',{name:'Email',exact:true}).fill('preview@example.test')
 if(category==='Players'){
  await password.fill('synthetic-wrong');await signIn.click()
  await expect(account.getByRole('alert')).toContainText('Could not sign in')
 }
