test('Explore match history pagination restores the exact scorecard row on return',async({page})=>{
 await page.setViewportSize({width:320,height:640})
 await page.goto(origin+'/?large=1&explore-return=1&repeat-opponents=1&long-match-history=1')
 await page.locator('.app-navigation [data-screen="explore"]').click()
 const query=page.locator('#native-search-term')
 await query.fill('Jordan')
 await query.press('Enter')
 await page.getByRole('button',{name:'View player Jordan Lee 1',exact:true}).click()

 const matchesTab=page.getByRole('navigation',{name:'Player sections',exact:true}).getByRole('button',{name:'View player matches',exact:true})
 await matchesTab.click()
 const history=page.getByRole('region',{name:'Public match history',exact:true})
 const rows=history.getByRole('listitem')
 await expect(history.getByRole('status')).toContainText('Showing 20 of 41 recorded results')
 await expect(rows).toHaveCount(20)
 await history.getByRole('button',{name:'Show 20 more results',exact:true}).click()
 await expect(rows).toHaveCount(40)
 const nextScorecard=rows.nth(20).getByRole('button',{name:/Open full scorecard/})
 await expect(nextScorecard).toBeFocused()
 await expect(nextScorecard).toBeInViewport({ratio:1})
 const historyScroll=await page.evaluate(()=>window.scrollY)
 await nextScorecard.click()
 const scorecard=page.locator('#match-detail')
 await expect(scorecard.getByRole('heading',{name:'Match scorecard',exact:true})).toBeFocused()
 await expect(scorecard.locator('#match-players')).toHaveAttribute('data-state','ready')
 const back=scorecard.getByRole('button',{name:'Back to match history',exact:true})
 await scorecard.getByRole('heading',{name:'Players on court',exact:true}).evaluate(el=>el.scrollIntoView({block:'center'}))
 await expect.poll(()=>back.evaluate(button=>{
  const {top,left,width,height}=button.getBoundingClientRect()
  const style=getComputedStyle(button)
  return {
   stuck:Math.abs(top-parseFloat(style.insetBlockStart))<=1,
   tappable:button.contains(document.elementFromPoint(left+width/2,top+height/2)),
   top,scroll:window.scrollY,position:style.position,
  }
 })).toMatchObject({stuck:true,tappable:true,position:'sticky'})
 await back.click()
 await expect(nextScorecard).toBeFocused()
 await expect(nextScorecard).toBeInViewport({ratio:1})
 await expect(rows).toHaveCount(40)
 expect(Math.abs(await page.evaluate(()=>window.scrollY)-historyScroll)).toBeLessThanOrEqual(2)
 await history.getByRole('button',{name:'Show 1 more result',exact:true}).click()
 await expect(rows).toHaveCount(41)
 await expect(rows.nth(40).getByRole('button',{name:/Open full scorecard/})).toBeFocused()
 await expect(history.getByText('All 41 results shown',{exact:true})).toBeVisible()
 await expect(history.getByRole('button',{name:/Show .* more result/})).toHaveCount(0)

 const rivals=page.getByRole('region',{name:'Repeat opponents',exact:true})
 await rivals.getByRole('button',{name:'View 41 meetings with Jordan Lee 2',exact:true}).click()
 const meetings=page.getByRole('region',{name:'Meetings with Jordan Lee 2',exact:true})
 const meetingRows=meetings.getByRole('listitem')
 await expect(meetingRows).toHaveCount(20)
 await meetings.getByRole('button',{name:'Show 20 more results',exact:true}).click()
 await expect(meetingRows).toHaveCount(40)
 await expect(meetingRows.nth(20).getByRole('button',{name:/Open full scorecard/})).toBeFocused()
 await matchesTab.click()
 await expect(rows).toHaveCount(41)
})

