 const updated={date:'2026-11-06',time:'18:15',location:'Riverside Tennis Center · Court 4'}
 const previousReply='2026-11-02T10:00:00.123456+00:00'
 await page.evaluate(({updated,previousReply})=>{
  const fixture=(window as unknown as CalendarPreviewWindow).calendarFixture
  Object.assign(fixture.competitions[0],updated,{responseIsStale:true,responseUpdatedAt:previousReply})
 },{updated,previousReply})
 await nextMatch.click()
 const calendar=page.getByRole('dialog',{name:'Your calendar',exact:true})
 const heading=calendar.getByRole('heading',{name:'Your availability',exact:true})
 await expect(heading).toBeFocused()
