async function openTrainingDirectionForWeek(page:Page,extra:string,kind:'style'|'focus',slug:string){
 await page.setViewportSize({width:320,height:844})
 await page.goto(origin+'/?large=1&training-inbox-review=1&'+extra)
 await page.getByRole('button',{name:'More',exact:true}).click()
 await page.locator('[data-app-destination="coach"]').click()
 await page.locator('[data-app-destination="training"]').click()
 const training=page.getByRole('dialog',{name:'Level Up training',exact:true})
 await training.getByText('More training tools',{exact:true}).click()
 await training.getByRole('button',{name:'Your direction',exact:true}).click()
 await training.getByRole('combobox',{name:kind==='style'?'Playing style':'Development focus',exact:true}).selectOption(slug)
 await training.getByRole('button',{name:`Train with this ${kind}`,exact:true}).click()
 return training
}
