test('My Lab player search offers a retry and team invite when no record matches',async({page},info)=>{
 await page.setViewportSize({width:320,height:844})
 await page.goto(origin+'/?unlinked=1&large=1&explore-empty=1')
 await page.locator('.preview-controls').evaluate(el=>{(el as HTMLElement).hidden=true})
 await page.getByRole('button',{name:'Find my player',exact:true}).click()
 const input=page.getByRole('searchbox',{name:'Your tennis name',exact:true})
 const submit=page.getByRole('button',{name:'Search players',exact:true})
 await input.fill('Missingville');await submit.click()
 const empty=page.locator('#player-choices .explore-search-empty')
 await expect(empty.getByRole('heading',{name:'No player records found',exact:true})).toBeVisible()
 await expect(empty).toHaveCSS('display','grid')
 await expect(page.locator('#player-search-status')).toHaveText('No player records found.')
 const invite=empty.getByRole('button',{name:'Use a team invite',exact:true})
 await invite.evaluate(el=>el.scrollIntoView({block:'center'}))
 expect(await invite.evaluate(el=>el.getBoundingClientRect().bottom<=document.querySelector('.app-navigation')!.getBoundingClientRect().top)).toBe(true)
 await bounded(page)
 await page.screenshot({path:info.outputPath('my-lab-player-search-empty.png')})
 await invite.click()
 const dialog=page.getByRole('dialog',{name:'Join a team',exact:true})
 await expect(dialog).toBeVisible()
 await dialog.getByRole('button',{name:'Close',exact:true}).click()
 await expect(invite).toBeFocused()
 await expect(input).toHaveValue('Missingville')
 const drill=page.getByRole('button',{name:'Try a drill',exact:true})
 await drill.click()
 const training=page.getByRole('dialog',{name:'Level Up training',exact:true})
 await expect(training.getByRole('heading',{name:'Split-Step Rhythm',exact:true})).toBeVisible()
 await training.getByRole('button',{name:'Close Level Up',exact:true}).click()
 await expect(drill).toBeFocused()
 await expect(input).toHaveValue('Missingville')
 await empty.getByRole('button',{name:'Edit search',exact:true}).click()
 await expect(input).toBeFocused()
 expect(await input.evaluate(el=>[(el as HTMLInputElement).selectionStart,(el as HTMLInputElement).selectionEnd])).toEqual([0,'Missingville'.length])
 await input.fill('Jordan Lee');await submit.click()
 await expect(empty).toHaveCount(0)
 await expect(page.getByRole('button',{name:'Review this record for Jordan Lee',exact:true})).toBeVisible()
})

