test('Team invite shows the exact team before the player joins',async({page},info)=>{
 await page.setViewportSize({width:320,height:844})
 await page.goto(origin+'/?unlinked=1&large=1')
 await page.getByRole('button',{name:'Use a team invite',exact:true}).click()
 const invite=page.getByRole('dialog',{name:'Join a team',exact:true})
 const field=invite.getByLabel('Team invite',{exact:true})
 const review=invite.getByRole('button',{name:'Review invite',exact:true})
 const actions=()=>page.evaluate(()=>(window as unknown as {navigationFixture:{teamInviteActions:string[]}}).navigationFixture.teamInviteActions)
 const link='https://www.tenaceiq.com/team-room/join?token=44444444-4444-4444-8444-444444444444'
 await field.fill('https://example.test/join')
 await review.click()
 await expect(invite.getByRole('status')).toContainText('Paste a valid TenAceIQ team invite')
 expect(await actions()).toEqual([])
 await field.fill(link)
 await field.press('Enter')
 await expect(invite.getByRole('heading',{name:'Baseline Aces',exact:true})).toBeFocused()
 await expect(invite).toContainText('City League')
 await expect(invite).toContainText('4.0')
 expect(await actions()).toEqual(['preview'])
 expect(await invite.evaluate(el=>el.scrollWidth<=el.clientWidth)).toBe(true)
 await page.screenshot({path:info.outputPath('team-invite-preview.png')})
 await invite.getByRole('button',{name:'Use a different invite',exact:true}).click()
 await expect(field).toBeFocused()
 await expect(field).toHaveValue(link)
 await expect(invite.getByRole('button',{name:'Join as player',exact:true})).toHaveCount(0)
 await review.click()
 await invite.getByRole('button',{name:'Join as player',exact:true}).click()
 await expect(invite).toHaveCount(0)
 await expect.poll(actions).toEqual(['preview','preview','join'])
 await expect.poll(()=>page.evaluate(()=>(window as unknown as {chatUnreadFixture:{opened:string[]}}).chatUnreadFixture.opened
  .some(query=>new URLSearchParams(query).get('team')==='Baseline Aces'))).toBe(true)
})

