test('shared court links show each player’s sets in a neutral scorecard',async({page})=>{
 await page.setViewportSize({width:320,height:640})
 await page.goto(origin+'/?large=1&explore-return=1&link='+encodeURIComponent('https://www.tenaceiq.com/matches/court-0?via=scorecard-share'))
 const score=page.getByRole('dialog',{name:'Shared match scorecard',exact:true})
 await expect(score.getByRole('heading',{name:'Match scorecard',exact:true})).toBeFocused()
 await expect(score.getByText('Side B won',{exact:true})).toBeVisible()
 await expect(score).not.toContainText('Your side')
 await expect(score.getByRole('button',{name:'Review scorecard sharing'})).toHaveCount(0)
 await expect(score.getByRole('button',{name:'Work on my game',exact:true})).toHaveCount(0)
 const table=score.getByRole('table',{name:'Scores for Side A and Side B',exact:true})
 const losingRow=table.locator('tbody tr').first()
 const winningRow=table.locator('tbody tr').last()
 await expect(losingRow.getByRole('rowheader')).toHaveText('Jordan Lee 2')
 await expect(winningRow.getByRole('rowheader')).toHaveText('Jordan Lee 1 Winner')
 await expect(losingRow.getByRole('cell')).toHaveText(['4','3'])
 await expect(winningRow.getByRole('cell')).toHaveText(['6','6'])
 await expect(winningRow).toHaveAttribute('data-match-winner','')
 expect(await score.evaluate(el=>el.scrollWidth<=el.clientWidth+1)).toBe(true)
 const close=score.getByRole('button',{name:'Close scorecard',exact:true})
 await expect(close).toHaveCount(1)
 const closeTop=await close.evaluate(el=>el.getBoundingClientRect().top)
 const lineup=score.getByRole('button',{name:'View lineup',exact:true})
 await lineup.click()
 await expect(score.getByRole('heading',{name:'Players on court',exact:true})).toBeFocused()
 await expect(score.getByRole('button',{name:'View player profile for Jordan Lee 1',exact:true})).toBeVisible()
 await score.getByRole('button',{name:'Set scores',exact:true}).click()
 await expect(score.getByRole('heading',{name:'Set by set',exact:true})).toBeFocused()
 await lineup.click()
 await expect.poll(()=>score.locator('.shared-match-body').evaluate(el=>el.scrollTop)).toBeGreaterThan(100)
 await expect(close).toBeInViewport({ratio:1})
 expect(Math.abs(await close.evaluate(el=>el.getBoundingClientRect().top)-closeTop)).toBeLessThanOrEqual(1)
 expect(await close.evaluate(el=>{
  const {left,top,width,height}=el.getBoundingClientRect()
  return el.contains(document.elementFromPoint(left+width/2,top+height/2))
 })).toBe(true)
 await close.tap()
 await expect(score).toHaveCount(0)
})

test('unavailable shared court links keep retry and close available',async({page})=>{
 await page.goto(origin+'/?link='+encodeURIComponent('https://www.tenaceiq.com/matches/missing-court?via=scorecard-share'))
 const score=page.getByRole('dialog',{name:'Shared match scorecard',exact:true})
 const unavailable=score.getByRole('heading',{name:'Scorecard unavailable',exact:true})
 await expect(unavailable).toBeFocused()
 const close=score.getByRole('button',{name:'Close scorecard',exact:true})
 await expect(close).toBeInViewport({ratio:1})
 await score.getByRole('button',{name:'Try again',exact:true}).click()
 await expect(unavailable).toBeFocused()
 await close.click()
 await expect(score).toHaveCount(0)
})
